	'rm_nesttab' => 'Nest',
	'close_p' => 'Venez voir les salles. Les visites ont lieu le mardi et le jeudi, à 10:00 et 16:00.',
	'close_cta' => 'Réserver une visite',
	'cdr_tm2' => 'Tout le monde se rassemble sur le tapis pour une chanson et un coup d’œil à la journée. Court, bruyant et aimé.',
	'cdr_tm4' => 'Le déjeuner est cuisiné ici le matin même et servi aux tables basses. Les éducatrices mangent avec les enfants, et les petites cuillères sont les bienvenues.',
	'cdr_tm5' => 'Rideaux à moitié tirés, lits bas, une couverture de la maison si vous voulez. Certains enfants dorment et d’autres se reposent, et les deux sont très bien.',
	'cdr_tm6' => 'Des fruits et un biscuit nature ou un toast de la même cuisine, servis avant les jeux d’atelier.',
	'cdr_tm7' => 'Peinture, cubes, eau et musique dans les salles, tablier mis, désordre attendu.',
	'cdr_tm9' => 'Les derniers enfants sont récupérés et la porte ferme à 18:30. Si vous avez besoin de cette heure tardive, dites-le-nous à l’arrivée.',
	'cd_rhythm_tab' => 'Nest',
	'rm_l_ages' => 'Âges',
	'rm_l_ratio' => 'Taux',
	'rm_l_places' => 'Places',
	'rm_l_key' => 'Responsable de salle',
	'rm_l_rest' => 'Repos',
	'rm1_ages' => '4 à 15 mois',
	'rm1_ratio' => '1 éducatrice pour 3 bébés',
	'rm1_places' => '9 places',
	'rm1_key' => 'Samuel Osei',
